// @pit: {"label": "Review draft v2.5.0 release, publish it, and confirm v2 tag points at it"}
async ({ shell: { execFile } }) => {
  const d = await execFile("gh", ["release", "view", "v2.5.0", "--json", "isDraft,tagName,body"]);
  const j = JSON.parse(d.stdout);
  const ok = j.body.includes("thinking_level") && j.body.includes("Full Changelog") && !j.body.includes("vX.Y.Z");
  if (!ok) return { stop: true, body: j.body.slice(0, 1500) };
  const e = await execFile("gh", ["release", "edit", "v2.5.0", "--draft=false", "--latest"]);
  const [rel, tags] = await Promise.all([
    execFile("gh", ["release", "view", "v2.5.0", "--json", "isDraft,url"]),
    execFile("git", ["ls-remote", "--tags", "origin", "v2", "v2.5.0^{}"]),
  ]);
  return { edit: e.code + e.stderr, rel: rel.stdout, tags: tags.stdout, tail: j.body.slice(-200) };
}
